-- Full schema (pre-production: recreate the database from this file instead of
-- running incremental migrations).
--
-- Cards have a front and a back (each an ordered list of blocks). A front
-- board can additionally carry a back layer (solutionFrom/solutionAnnotations
-- inside its JSON): moves and annotations hidden in study until the card is
-- turned.

-- better-auth managed tables (schema generated by its CLI, adapted to uuid ids
-- to match the domain tables' user_id columns)
create table "user" (
	"id" uuid not null primary key,
	"name" text not null,
	"email" text not null unique,
	"emailVerified" boolean not null,
	"image" text,
	"createdAt" timestamptz default current_timestamp not null,
	"updatedAt" timestamptz default current_timestamp not null,
	-- app fields (better-auth additionalFields)
	"isAdmin" boolean default false not null,
	"pieceSet" text default 'standard' not null,
	"boardTheme" text default 'default' not null,
	"borderType" text default 'black' not null,
	"showCoordinates" boolean default true not null,
	-- The board always tints the two squares of the move that led to the
	-- position it opens on; with this, of every move it is stepped to as well.
	"highlightEveryMove" boolean default false not null,
	"animationDuration" integer default 150 not null,
	-- the hour a new study day begins ("next day starts at", Anki's 4am): a
	-- card scheduled a day or more out waits for this boundary rather than
	-- for the clock time it was graded at, so studying past midnight is still
	-- the same day's session. The zone it is read in comes from the browser.
	"rolloverHour" smallint default 4 not null check ("rolloverHour" between 0 and 23),
	-- whose games "Import from a game" lists; asked for once, on that page
	"chesscomUsername" text,
	"lichessUsername" text,
	"twoFactorEnabled" boolean default false not null
);

-- display names are public (a review is signed with one), so no two accounts
-- share one, whatever the case
create unique index user_name_key on "user" (lower("name"));

create table "session" (
	"id" uuid not null primary key,
	"expiresAt" timestamptz not null,
	"token" text not null unique,
	"createdAt" timestamptz default current_timestamp not null,
	"updatedAt" timestamptz not null,
	"ipAddress" text,
	"userAgent" text,
	"userId" uuid not null references "user" ("id") on delete cascade,
	"twoFactorVerified" boolean default false not null
);

create table "account" (
	"id" uuid not null primary key,
	"accountId" text not null,
	"providerId" text not null,
	"userId" uuid not null references "user" ("id") on delete cascade,
	"accessToken" text,
	"refreshToken" text,
	"idToken" text,
	"accessTokenExpiresAt" timestamptz,
	"refreshTokenExpiresAt" timestamptz,
	"scope" text,
	"password" text,
	"createdAt" timestamptz default current_timestamp not null,
	"updatedAt" timestamptz not null
);

create table "verification" (
	"id" uuid not null primary key,
	"identifier" text not null,
	"value" text not null,
	"expiresAt" timestamptz not null,
	"createdAt" timestamptz default current_timestamp not null,
	"updatedAt" timestamptz default current_timestamp not null
);

create table "twoFactor" (
	"id" uuid not null primary key,
	"secret" text not null,
	"backupCodes" text not null,
	"userId" uuid not null references "user" ("id") on delete cascade,
	"verified" boolean default true not null,
	"failedVerificationCount" integer default 0 not null,
	"lockedUntil" timestamptz
);

create index "session_userId_idx" on "session" ("userId");
create index "account_userId_idx" on "account" ("userId");
create index "twoFactor_userId_idx" on "twoFactor" ("userId");
create index "twoFactor_secret_idx" on "twoFactor" ("secret");
create index "verification_identifier_idx" on "verification" ("identifier");

create type deck_theme as enum ('openings', 'endgames', 'tactics', 'strategy', 'checkmates');

-- every user reference cascades so better-auth's account deletion can remove
-- a user together with everything they own
create table decks (
	id uuid primary key default gen_random_uuid(),
	user_id uuid references "user" ("id") on delete cascade not null,
	name text not null,
	-- Decks nest, as Anki's do: parent_id is the deck this one sits inside,
	-- null at the top of My flashcards. A deck goes with everything inside
	-- it. It holds cards and decks both, its own cards coming first.
	parent_id uuid references decks(id) on delete cascade,
	-- its place among its siblings, 1..n, shared with the marketplace decks
	-- taken that sit beside it; the user drags to reorder, and a new deck
	-- joins at the end
	position integer not null default 0,
	-- How the decks inside it are studied: in order (each opens once the one
	-- before has passed — all seen, most graduated — its own cards counting
	-- as the first), or mixed (all open, new cards taken from each in turn).
	-- The deck's own say, wherever study starts from (lib/deck-tree.js).
	in_order boolean not null default true,
	-- How the cards due for review come: shuffled, or in the order new cards
	-- come (for lines seen in sequence, like openings). Read on the deck at
	-- the top of the list only; everything inside it follows it.
	reviews_in_order boolean not null default false,
	-- The days a solved tactic card waits, step by step; one more solve after
	-- the last retires it. Null: the nearest deck above's, or else the
	-- default (lib/deck-tree.js).
	tactic_ladder int[],
	-- the deck's own listing (its Deck tab): an upload request starts from
	-- it, and editing it never reaches a listing already on the marketplace.
	-- A description is blocks, like a card's side (text and boards), and the
	-- sample cards are ordered ids of the cards under it
	description jsonb,
	theme deck_theme,
	image bytea,
	image_type text,
	preview_card_ids uuid[] not null default '{}',
	-- a name says which deck it is among its siblings only, as Anki's full
	-- name does: two courses can each have a "Chapter 1"
	unique nulls not distinct (user_id, parent_id, name)
);

-- Tactic cards are graded Correct/Incorrect instead of FSRS: Correct climbs
-- their deck's ladder (reps is the rung) and past its last step finishes the
-- card for good (finished_at); Incorrect starts it over a day later. Articles
-- (first exposure articles) are a page read once, before the cards after
-- them: reading one finishes it (finished_at, last_review). Neither carries
-- FSRS memory state, so the FSRS columns stay null for them (state is the
-- constraint's representative for the group).
create table cards (
	id uuid primary key default gen_random_uuid(),
	-- the deck the card sits in; position is its place there, 1..n
	deck_id uuid references decks(id) on delete cascade not null,
	position smallint not null,
	front jsonb not null,
	back jsonb,
	card_type text not null default 'basic' check (card_type in ('basic', 'tactic', 'article')),
	finished_at timestamptz,
	due timestamptz not null,
	stability numeric,
	difficulty numeric,
	elapsed_days smallint,
	scheduled_days smallint,
	reps smallint,
	lapses smallint,
	learning_steps smallint,
	state smallint check(state between 0 and 3),
	last_review timestamptz,
	constraint only_basic_cards_have_fsrs_state check ((card_type = 'basic') = (state is not null))
);

create table marketplace_decks (
	id uuid primary key default gen_random_uuid(),
	-- null once the author has deleted their account; author_name keeps the
	-- name they last had
	user_id uuid references "user" ("id") on delete set null,
	author_name text,
	-- the author's id after they deleted their account, for the payouts
	-- still owed to them
	former_author_id uuid,
	on_sale boolean not null default true,
	-- set when an admin takes the deck down, and sent to the author
	taken_down_reason text,
	name text not null unique,
	description jsonb not null,
	price numeric(5,2) check(price >= 0) not null,
	theme deck_theme not null,
	image bytea not null,
	image_type text not null,
	-- the author's in order / mixed for the decks inside it (as decks.in_order),
	-- which every copy starts from
	in_order boolean not null default true,
	-- the author's shuffled / in order for its reviews (as decks.reviews_in_order)
	reviews_in_order boolean not null default false,
	-- the author's tactic ladder (as decks.tactic_ladder), as it stood for
	-- the published deck where it sat
	tactic_ladder int[],
	-- the author's deck it was published from, while they keep it
	deck_id uuid references decks(id) on delete set null,
	-- the author agreement accepted with the upload request, kept here since
	-- the request goes with the author's deck
	author_terms_version text
);

-- where an author's earnings are paid, by Wise to an email; not tied to
-- the user row, since it outlives a deleted account until the last payout.
-- A new email waits for the link sent to the account's email.
create table payout_details (
	user_id uuid primary key,
	email text,
	-- as on their bank account, and its currency, for Wise
	name text,
	currency text,
	changed_at timestamptz,
	pending_email text,
	pending_token_hash text unique,
	pending_expires_at timestamptz
);

-- An author's earnings for the sales before period_end, less refunds of
-- sales paid before; prepared, then paid by a Wise batch. Deleting one
-- puts its sales and refunds back to be paid.
create table payouts (
	id uuid primary key default gen_random_uuid(),
	author_id uuid not null,
	period_end date not null,
	amount_cents integer not null check (amount_cents > 0),
	email text not null,
	name text not null,
	currency text not null,
	created_at timestamptz not null default now(),
	paid_at timestamptz
);
create index payouts_author_id_idx on payouts (author_id);

-- an author who deletes their account leaves their decks with those who
-- have them, off sale
create function keep_authors_decks() returns trigger language plpgsql as $$
begin
	-- payout details stay only while something is owed
	if not exists (select 1 from purchases p join marketplace_decks md on md.id = p.marketplace_deck_id
		where md.user_id = old.id and p.payout_id is null and p.refunded_at is null and p.author_share_cents is not null) then
		delete from payout_details where user_id = old.id;
	end if;
	update marketplace_decks set author_name = old.name, former_author_id = old.id, on_sale = false,
		user_id = null, deck_id = null
	where user_id = old.id;
	return old;
end $$;
create trigger keep_authors_decks before delete on "user"
	for each row execute function keep_authors_decks();

-- the decks inside a published deck, tree and all, copied from the author's
-- at upload approval (parent_id null: directly inside the published deck)
create table marketplace_subdecks (
	id uuid primary key default gen_random_uuid(),
	marketplace_deck_id uuid references marketplace_decks(id) on delete cascade not null,
	parent_id uuid references marketplace_subdecks(id) on delete cascade,
	name text not null,
	position smallint not null,
	in_order boolean not null default true,
	tactic_ladder int[]
);

create table marketplace_cards (
	id uuid default gen_random_uuid() primary key,
	marketplace_deck_id uuid references marketplace_decks(id) on delete cascade not null,
	-- the deck inside it the card sits in; null for the published deck's own
	subdeck_id uuid references marketplace_subdecks(id),
	position smallint not null,
	front jsonb not null,
	back jsonb,
	card_type text not null default 'basic' check (card_type in ('basic', 'tactic', 'article')),
	-- position among the deck's public preview cards; null = not in the preview
	preview_order smallint
);

create table marketplace_deck_instances (
	id uuid primary key default gen_random_uuid(),
	user_id uuid references "user" ("id") on delete cascade not null,
	marketplace_deck_id uuid references marketplace_decks(id) not null,
	-- The deck of the user's own it sits inside, null at the top; when that
	-- deck is deleted it comes to the top, since it was taken, not made.
	-- position is its place among its siblings, as decks.position.
	parent_id uuid references decks(id) on delete set null,
	position integer not null default 0,
	-- The studier's own in order / mixed where it differs from the author's,
	-- for the deck itself (under this instance's id) and each deck inside it
	-- (under its marketplace_subdecks id): { "<id>": true | false }.
	in_order_overrides jsonb not null default '{}',
	-- the studier's own shuffled / in order for its reviews; null: the author's
	reviews_in_order boolean,
	unique (user_id, marketplace_deck_id)
);

create table purchases (
	id uuid primary key default gen_random_uuid(),
	user_id uuid references "user" ("id") on delete set null,
	marketplace_deck_id uuid references marketplace_decks(id) not null,
	price_cents integer not null check (price_cents >= 0),
	currency text not null default 'usd',
	tax_cents integer,
	fee_cents integer,
	author_share_cents integer,
	stripe_checkout_session_id text unique,
	stripe_payment_intent_id text unique,
	terms_version text,
	created_at timestamptz not null default now(),
	refunded_at timestamptz,
	-- the payout that paid the author's share, and the one that took it
	-- back after a refund
	payout_id uuid references payouts(id) on delete set null,
	clawback_payout_id uuid references payouts(id) on delete set null
);

create unique index purchases_owned_key on purchases (user_id, marketplace_deck_id) where refunded_at is null;

create table marketplace_card_instances (
	id uuid default gen_random_uuid() primary key,
	marketplace_deck_instance_id uuid references marketplace_deck_instances(id) on delete cascade not null,
	marketplace_card_id uuid references marketplace_cards(id) on delete cascade not null,
	card_type text not null default 'basic' check (card_type in ('basic', 'tactic', 'article')),
	finished_at timestamptz,
	due timestamptz not null,
	stability numeric,
	difficulty numeric,
	elapsed_days smallint,
	scheduled_days smallint,
	reps smallint,
	lapses smallint,
	learning_steps smallint,
	state smallint check(state between 0 and 3),
	last_review timestamptz,
	constraint only_basic_instances_have_fsrs_state check ((card_type = 'basic') = (state is not null))
);

-- tactic reviews log only rating + review time (+ due when re-queued), so the
-- FSRS columns are nullable.
-- A log names the card it was of, one of the two kinds. Plain ids, not
-- references: a log outlives its card and keeps naming it, so a deleted
-- card's reviews still read as one card's history (as Anki's revlog keeps its
-- card id) for the FSRS optimizer, which trains on whole histories. The
-- answer was given that day whatever became of the card, and the activity
-- heatmap goes on counting it.
create table review_logs (
	id uuid primary key default gen_random_uuid(),
	user_id uuid references "user" ("id") on delete cascade not null,
	card_id uuid,
	marketplace_card_instance_id uuid,
	rating smallint check(rating between 0 and 4) not null,
	state smallint check(state between 0 and 3),
	due timestamptz,
	stability numeric,
	difficulty numeric,
	elapsed_days smallint,
	last_elapsed_days smallint,
	scheduled_days smallint,
	learning_steps smallint,
	review timestamptz not null,
	check (card_id is null or marketplace_card_instance_id is null)
);

-- Upload requests carry the marketplace listing details (name, description,
-- price, thumbnail) and the ordered card ids chosen as the public preview;
-- approval copies everything into the marketplace tables.
create table marketplace_upload_requests (
	id uuid primary key default gen_random_uuid(),
	deck_id uuid references decks(id) on delete cascade not null,
	user_id uuid references "user" ("id") on delete cascade not null,
	name text not null,
	description jsonb not null,
	theme deck_theme not null,
	price numeric(5,2) check(price >= 0) not null,
	image bytea not null,
	image_type text not null,
	preview_card_ids uuid[] not null default '{}',
	status text check(status in ('pending', 'approved', 'rejected')) not null default 'pending',
	-- admins reject with a reason that is shown to the requester
	rejection_reason text,
	author_terms_version text,
	created_at timestamptz not null default now()
);

-- A studier's verdict on a marketplace deck, as Steam's: recommended or not,
-- always with the reason in words. One per user and deck. It can be rewritten
-- for a few minutes after it is posted and is then fixed (delete it to write
-- another), so the votes and the author's response are always about the text
-- that is there.
create table marketplace_reviews (
	id uuid primary key default gen_random_uuid(),
	marketplace_deck_id uuid references marketplace_decks(id) on delete cascade not null,
	user_id uuid references "user" ("id") on delete cascade not null,
	recommended boolean not null,
	body text not null check (length(trim(body)) > 0),
	-- the deck author's one reply to the review
	author_response text,
	author_response_at timestamptz,
	created_at timestamptz not null default now(),
	unique (marketplace_deck_id, user_id)
);

-- whether a reader found a review helpful (1) or not (-1); the deck is the
-- review's, so it is not repeated here
create table marketplace_review_votes (
	review_id uuid references marketplace_reviews(id) on delete cascade not null,
	user_id uuid references "user" ("id") on delete cascade not null,
	value smallint not null check (value in (-1, 1)),
	primary key (review_id, user_id)
);

-- Answers given as practice in a cram session. They change no schedule and
-- are no part of a card's review history (review_logs is what scheduling
-- reads), but they are study done, and the activity heatmap counts them. A
-- log outlives its card: the day's work was done whatever became of it.
create table practice_logs (
	id uuid primary key default gen_random_uuid(),
	user_id uuid references "user" ("id") on delete cascade not null,
	card_id uuid references cards(id) on delete set null,
	marketplace_card_instance_id uuid references marketplace_card_instances(id) on delete set null,
	got_it boolean not null,
	answered timestamptz not null default now()
);

-- A cram session gone through to the end: by whom, when, and on what (the
-- deck crammed: one of the user's own, a marketplace deck taken, or a deck
-- inside one). A plain id, not a reference: it is a record of study done,
-- kept whatever becomes of the deck. Study's end screen counts the day's
-- from it.
create table cram_sessions (
	id uuid primary key default gen_random_uuid(),
	user_id uuid references "user" ("id") on delete cascade not null,
	studied uuid not null,
	completed timestamptz not null default now()
);

-- An index behind every foreign key that has none of its own (a primary key
-- or a unique constraint leading with it): Postgres makes none for the
-- referencing side, and without one each "the cards of this deck" is a scan
-- of the whole table, as is each cascade when a row above goes.
create index cards_deck_id_idx on cards (deck_id);
create index decks_parent_id_idx on decks (parent_id);
create index marketplace_decks_user_id_idx on marketplace_decks (user_id);
create index marketplace_subdecks_marketplace_deck_id_idx on marketplace_subdecks (marketplace_deck_id);
create index marketplace_subdecks_parent_id_idx on marketplace_subdecks (parent_id);
create index marketplace_cards_marketplace_deck_id_idx on marketplace_cards (marketplace_deck_id);
create index marketplace_cards_subdeck_id_idx on marketplace_cards (subdeck_id);
create index marketplace_deck_instances_parent_id_idx on marketplace_deck_instances (parent_id);
create index marketplace_deck_instances_marketplace_deck_id_idx on marketplace_deck_instances (marketplace_deck_id);
create index marketplace_card_instances_marketplace_deck_instance_id_idx on marketplace_card_instances (marketplace_deck_instance_id);
create index marketplace_card_instances_marketplace_card_id_idx on marketplace_card_instances (marketplace_card_id);
create index review_logs_user_id_idx on review_logs (user_id);
create index review_logs_card_id_idx on review_logs (card_id);
create index review_logs_marketplace_card_instance_id_idx on review_logs (marketplace_card_instance_id);
create index marketplace_upload_requests_user_id_idx on marketplace_upload_requests (user_id);
create index marketplace_upload_requests_deck_id_idx on marketplace_upload_requests (deck_id);
create index marketplace_reviews_user_id_idx on marketplace_reviews (user_id);
create index marketplace_review_votes_user_id_idx on marketplace_review_votes (user_id);
create index cram_sessions_user_id_idx on cram_sessions (user_id);
create index practice_logs_user_id_idx on practice_logs (user_id);
create index practice_logs_card_id_idx on practice_logs (card_id);
create index practice_logs_marketplace_card_instance_id_idx on practice_logs (marketplace_card_instance_id);
